"use strict";
const SAVE_KEY="combat-v0-solo-test-v8";
const $=s=>document.querySelector(s), app=$("#app"), modalRoot=$("#modalRoot");
const deep=x=>JSON.parse(JSON.stringify(x));
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const roll=()=>Math.floor(Math.random()*100)+1;

const PC_TEMPLATES=[
 {id:"ardan",name:"Ardan",role:"Polearm Mercenary",hp:250,stamina:20,mana:0,def:10,defenseBonus:40,abilities:[
  A("strike","Polearm Strike",1,0,0,55,0,0,"attack",45),A("thrust","Impaling Thrust",2,3,0,75,0,0,"attack",45),A("sweep","Sweeping Arc",2,4,0,45,0,0,"multi",0,2,3),A("rush","Lancer's Rush",1,3,0,55,0,0,"rush",45),A("lacerate","Lacerating Strike",2,3,0,55,0,0,"bleed",45)]},
 {id:"sera",name:"Sera",role:"Sword-and-Shield Guardian",hp:275,stamina:20,mana:0,def:20,defenseBonus:40,abilities:[
  A("strike","Sword Strike",1,0,0,35,0,0,"attack",30),A("bash","Shield Bash",1,3,0,45,0,0,"push",45)]},
 {id:"mira",name:"Mira",role:"Storm Mage",hp:250,stamina:15,mana:20,def:5,defenseBonus:20,abilities:[
  A("touch","Storm Touch",1,0,2,60,0,0,"attack",45),A("bolt","Lightning Bolt",1,0,2,60,0,1,"attack",45),A("gust","Gust",1,0,3,60,0,1,"push",45)]},
 {id:"elian",name:"Elian",role:"Holy Mage",hp:250,stamina:15,mana:20,def:5,defenseBonus:20,abilities:[
  A("touch","Holy Touch",1,0,2,55,0,0,"attack",45),A("bolt","Radiant Bolt",1,0,2,55,0,1,"attack",45),A("mend","Mend",1,0,3,50,0,1,"heal",0),A("wave","Renewing Wave",2,0,5,40,0,1,"multiheal",0,2,3)]}
];
function A(id,name,ap,stamina,mana,power,minRange,maxRange,type,attackBonus,minTargets=1,maxTargets=1){return{id,name,ap,stamina,mana,power,minRange,maxRange,type,attackBonus,minTargets,maxTargets}}
const ENCOUNTERS={
 bandits:{name:"Bandit Camp",zones:["Approach","Gate","Camp","Command Tent","Watchtower"],links:[[0,1,1],[1,2,1],[2,3,1],[2,4,2]],start:0,enemies:()=>[
  ...Array.from({length:4},(_,i)=>E(`melee${i+1}`,`Melee Bandit ${i+1}`,80,2,35,5,35,30,1,"melee")),...Array.from({length:4},(_,i)=>E(`archer${i+1}`,`Archer ${i+1}`,70,2,35,5,35,30,4,"archer")),E("bruiser","Bruiser",160,3,50,10,20,20,2,"bruiser"),E("leader","Leader",140,3,45,10,20,20,3,"leader")]},
 troll:{name:"The Troll",zones:["Cave Mouth","Troll's Den","Rocky Ledge"],links:[[0,1,1],[1,2,1]],start:0,enemies:()=>[E("troll","Troll",1200,3,60,20,10,15,1,"troll")]}
};
function E(id,name,hp,maxAp,atk,def,dodge,threat,zone,type){return{id,name,hp,maxHp:hp,ap:maxAp,maxAp,atk,def,dodge,threat,zone,type,side:"npc",conditions:[],alive:true,rallied:false,reckless:false,edges:0,enraged:false}}
const surveyQuestions=["What decisions do you remember making?","Which decision was hardest? What information did you use?","When were you unsure what you were allowed to do?","Which option felt obviously best? Which felt useless?","When did you choose to retain AP instead of spending it on your turn?","When did you spend or conserve stamina, mana, or Inventory Points? Why?","Where did combat slow down?","Before a defense roll, what did you expect to happen? Did the result match that expectation?","Did your position on the battlefield change your decisions? Describe when.","What did the combat rules encourage your party to do together?"];
let state=load()||{screen:"setup",mode:null,results:[],survey:{},battle:null,tweaks:null};

function npcDefaults(stats){return{...stats,control:"rigid",aiBehavior:"optimal_killer",defendPolicy:"existing",defendOdds:50,defendHpThreshold:50}}
function defaultTweaks(){return{pcs:Object.fromEntries(PC_TEMPLATES.map(p=>[p.id,{hp:p.hp,stamina:p.stamina,mana:p.mana,ip:3,ap:3,def:p.def,defenseBonus:p.defenseBonus,control:"manual",aiBehavior:"role_faithful"}])),bandits:{melee:npcDefaults({count:4,hp:80,ap:2,atk:35,def:5,dodge:35,threat:30}),archer:npcDefaults({count:4,hp:70,ap:2,atk:35,def:5,dodge:35,threat:30}),bruiser:npcDefaults({count:1,hp:160,ap:3,atk:50,def:10,dodge:20,threat:20}),leader:npcDefaults({count:1,hp:140,ap:3,atk:45,def:10,dodge:20,threat:20})},troll:{troll:{...npcDefaults({count:1,hp:1200,ap:3,atk:60,def:20,dodge:10,threat:15}),bossEdgesEnabled:true}},placements:{bandits:null,troll:null}}}

function load(){try{return JSON.parse(localStorage.getItem(SAVE_KEY))}catch{return null}}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$("#saveStatus").textContent="Autosaved locally · "+new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}catch{$("#saveStatus").textContent="Browser blocked local autosave"}}
function defenseTarget(pc,enemy){return enemy.threat+pc.defenseBonus}
function commit(){save();render()}
function log(text,kind="system"){state.battle.log.push({text,kind,t:Date.now()});save()}
function distance(a,b){if(a===b)return 0;let q=[[a,0]],seen=new Set([a]);while(q.length){let[n,d]=q.shift();for(const [x,y,c] of state.battle.links){let z=x===n?y:y===n?x:null;if(z!==null&&!seen.has(z)){if(z===b)return d+c;seen.add(z);q.push([z,d+c])}}}return 99}
function adjacent(zone){return state.battle.links.filter(x=>x[0]===zone||x[1]===zone).map(x=>({zone:x[0]===zone?x[1]:x[0],cost:x[2]}))}
function qualitative(tn){if(tn>=80)return"Easy to achieve a full result";if(tn>=60)return"Likely to achieve a full result";if(tn>=40)return"Uncertain";if(tn>=20)return"Unlikely to achieve a full result";return"Extremely dangerous"}

function setupView(){app.innerHTML=`<section class="panel setup"><p class="eyebrow">Solo combat test rig</p><h2>Choose a test</h2><p>PCs and enemy archetypes can be controlled manually, by deterministic doctrines, or by the ChatGPT API. The rules engine validates every action, rolls automatically, and records objective playtest evidence.</p><div class="mode-grid"><button class="mode" data-mode="bandits"><strong>Bandit Camp</strong><span>Independent group-combat test.</span></button><button class="mode" data-mode="troll"><strong>The Troll</strong><span>Independent boss test.</span></button></div><details class="doctrine"><summary>Rigid GM Doctrine</summary>${doctrine()}</details>${state.results.length?`<hr><h3>Saved results</h3><p>${state.results.length} completed encounter(s) remain in this browser.</p>`:""}</section>`;document.querySelectorAll("[data-mode]").forEach(b=>b.onclick=()=>startMode(b.dataset.mode))}
function doctrine(){return`<ol><li>Enemy decisions use fixed priorities and stable tie-breakers: lowest HP percentage, then lowest current HP, then Ardan → Sera → Mira → Elian.</li><li>Enemies Defend against the highest-power legal single-target attack when they have AP; ordinary bandits retain at most 1 AP, bosses retain according to their behavior.</li><li>Enemies pursue the nearest conscious PC, breaking distance ties by the target rule above. They never retreat or use morale.</li><li>Bandit roles use their named ability whenever legal; otherwise they move toward or Strike the chosen target. The leader Rallies up to four allies when at least two are available.</li><li>The troll follows the packet behavior. It Recovers Persistent Damage with an Edge when that would restore Regeneration this round, Sweeps two or more targets, and otherwise attacks the selected target.</li><li>No finishing blows are attempted: these foes prioritize conscious threats. This is a coded GM ruling because RAW makes the decision motive-dependent.</li></ol>`}
function startMode(mode){state.mode=mode;state.results=[];state.survey={};state.tweaks=defaultTweaks();state.screen="tweaks";commit()}
function numberField(path,label,value,min=0,disabled=false){let explanation=disabled?' title="Reset placement to change unit counts."':'';return`<label${explanation}>${label}<input type="number" min="${min}" step="1" value="${value}" data-tweak="${path}" ${disabled?'disabled aria-disabled="true"':''}></label>`}
function toggleField(path,label,checked){return`<label class="toggle"><input type="checkbox" data-toggle="${path}" ${checked?'checked':''}>${label}</label>`}
function pcControl(path,value){return`<label class="select-field">Control<select data-control="${path}.control"><option value="manual" ${value==="manual"?"selected":""}>Manual</option><option value="allout" ${value==="allout"?"selected":""}>All-Out Attacker</option><option value="prepared" ${value==="prepared"?"selected":""}>Always Prepared</option><option value="survivor" ${value==="survivor"?"selected":""}>Reactive Survivor</option><option value="ai" ${value==="ai"?"selected":""}>ChatGPT API</option></select></label>`}
function defendControls(path,s){return`<label class="select-field">Defend timing<select data-policy="${path}.defendPolicy"><option value="existing" ${s.defendPolicy==="existing"?"selected":""}>Existing doctrine</option><option value="random" ${s.defendPolicy==="random"?"selected":""}>Randomized</option><option value="always" ${s.defendPolicy==="always"?"selected":""}>Always</option><option value="hp" ${s.defendPolicy==="hp"?"selected":""}>At or below HP threshold</option></select></label><label class="range-field" ${s.defendPolicy==="random"?"":"hidden"}>Defend odds <output>${s.defendOdds}%</output><input type="range" min="0" max="100" step="1" value="${s.defendOdds}" data-range="${path}.defendOdds"></label><label class="range-field" ${s.defendPolicy==="hp"?"":"hidden"}>HP threshold <output>${s.defendHpThreshold}%</output><input type="range" min="0" max="100" step="1" value="${s.defendHpThreshold}" data-range="${path}.defendHpThreshold"></label>`}
function setTweak(path,value){let parts=path.split("."),obj=state.tweaks;for(const p of parts.slice(0,-1))obj=obj[p];obj[parts.at(-1)]=value}
function placementFor(key){return state.tweaks?.placements?.[key]||null}
function placementCounts(key){return Object.fromEntries(Object.entries(state.tweaks[key]).map(([type,settings])=>[type,settings.count]))}
function defaultPlacement(key){let c=ENCOUNTERS[key];return{pcs:Object.fromEntries(PC_TEMPLATES.map(p=>[p.id,c.start])),enemies:Object.fromEntries(makeConfiguredEnemies(key).map(e=>[e.id,e.zone])),counts:placementCounts(key)}}
function placementUnitIds(key){let placement=defaultPlacement(key);return{pcs:Object.keys(placement.pcs).sort(),enemies:Object.keys(placement.enemies).sort()}}
function validPlacement(key,draft){if(!draft||!draft.pcs||!draft.enemies)return false;let expected=placementUnitIds(key),actual={pcs:Object.keys(draft.pcs).sort(),enemies:Object.keys(draft.enemies).sort()},zones=ENCOUNTERS[key].zones.length;if(expected.pcs.join("|")!==actual.pcs.join("|")||expected.enemies.join("|")!==actual.enemies.join("|"))return false;return[...Object.values(draft.pcs),...Object.values(draft.enemies)].every(zone=>Number.isInteger(zone)&&zone>=0&&zone<zones)}
function applyPlacement(key,draft){if(!validPlacement(key,draft))return false;state.tweaks.placements[key]={pcs:deep(draft.pcs),enemies:deep(draft.enemies),counts:placementCounts(key)};return true}
function movePlacementUnit(draft,side,id,zone,key){if(!["pcs","enemies"].includes(side)||!Object.hasOwn(draft[side]||{},id)||!Number.isInteger(zone)||zone<0||zone>=ENCOUNTERS[key].zones.length)return false;draft[side][id]=zone;return true}
function placementLinks(key,zone){let c=ENCOUNTERS[key],links=c.links.filter(([a,b])=>a===zone||b===zone).map(([a,b,cost])=>`${c.zones[a===zone?b:a]} (${cost} AP)`);return links.length?`<small>Links: ${links.join(", ")}</small>`:""}
function placementToken(side,id,name,selected){let active=selected?.side===side&&selected.id===id;return`<button class="placement-token ${side==="pcs"?"pc":"enemy"} ${active?"selected":""}" draggable="true" data-placement-side="${side}" data-placement-id="${id}" aria-pressed="${active}">${name}</button>`}
function renderPlacementModal(key,draft,selected=null){let c=ENCOUNTERS[key],enemies=makeConfiguredEnemies(key),enemyNames=Object.fromEntries(enemies.map(e=>[e.id,e.name]));showModal(`<div class="placement-modal"><p class="eyebrow">${c.name}</p><h2>Unit Placement</h2><p>Drag each unit into any zone. You can also select a unit and then select a destination zone.</p><div class="placement-zones">${c.zones.map((name,zone)=>`<section class="placement-zone" data-placement-zone="${zone}"><h3>${name}</h3>${placementLinks(key,zone)}<div class="placement-tokens">${PC_TEMPLATES.filter(p=>draft.pcs[p.id]===zone).map(p=>placementToken("pcs",p.id,p.name,selected)).join("")}${enemies.filter(e=>draft.enemies[e.id]===zone).map(e=>placementToken("enemies",e.id,enemyNames[e.id],selected)).join("")}</div></section>`).join("")}</div><div class="placement-legend"><span class="token pc">Player character</span><span class="token enemy">Enemy</span></div><div class="footer-actions"><button id="cancelPlacement">Cancel</button><button id="applyPlacement" class="primary">Apply Placement</button></div></div>`,"placement-dialog");document.querySelectorAll("[data-placement-side]").forEach(token=>{token.onclick=event=>{event.stopPropagation();let next={side:token.dataset.placementSide,id:token.dataset.placementId};renderPlacementModal(key,draft,selected?.side===next.side&&selected.id===next.id?null:next)};token.ondragstart=event=>{event.dataTransfer.effectAllowed="move";event.dataTransfer.setData("text/plain",`${token.dataset.placementSide}|${token.dataset.placementId}`)}});document.querySelectorAll("[data-placement-zone]").forEach(zone=>{let destination=Number(zone.dataset.placementZone);zone.onclick=()=>{if(selected&&movePlacementUnit(draft,selected.side,selected.id,destination,key))renderPlacementModal(key,draft)};zone.ondragover=event=>{event.preventDefault();event.dataTransfer.dropEffect="move"};zone.ondrop=event=>{event.preventDefault();let[side,id]=event.dataTransfer.getData("text/plain").split("|");if(movePlacementUnit(draft,side,id,destination,key))renderPlacementModal(key,draft)}});$("#cancelPlacement").onclick=closeModal;$("#applyPlacement").onclick=()=>{if(!applyPlacement(key,draft))return;closeModal();commit()}}
function openPlacementModal(key){renderPlacementModal(key,deep(placementFor(key)||defaultPlacement(key)))}
function resetPlacement(key,ask=true){if(!placementFor(key))return;if(ask&&!confirm("Reset unit placement? Enemy counts will unlock and units will return to their published zones."))return;state.tweaks.placements[key]=null;commit()}
function tweakView(){let t=state.tweaks,k=state.mode,locked=Boolean(placementFor(k));app.innerHTML=`<section class="panel tweak-page"><p class="eyebrow">Pre-encounter setup</p><h2>Direct Stat Tweaks</h2><p>These values override the packet without applying character-building rules. Each PC and enemy archetype may use deterministic control or ChatGPT API control.</p>${aiSettingsHtml()}<section class="placement-setup"><div><h3>Unit Placement</h3><p>${locked?"Placement applied. Enemy counts are locked until placement is reset.":"Place individual PCs and enemies in any encounter zone before combat."}</p></div><div class="placement-actions"><button id="openPlacement">${locked?"Edit Placement":"Place Units"}</button>${locked?'<button id="resetPlacement">Reset Placement</button>':""}</div></section><h3>Player Characters</h3><div class="tweak-grid">${PC_TEMPLATES.map(p=>`<fieldset><legend>${p.name}</legend>${pcControl(`pcs.${p.id}`,t.pcs[p.id].control)}${aiBehaviorSelect(`pcs.${p.id}`,t.pcs[p.id].aiBehavior||"role_faithful","pc")}${numberField(`pcs.${p.id}.hp`,"HP",t.pcs[p.id].hp,1)}${numberField(`pcs.${p.id}.stamina`,"Stamina",t.pcs[p.id].stamina)}${numberField(`pcs.${p.id}.mana`,"Mana",t.pcs[p.id].mana)}${numberField(`pcs.${p.id}.ip`,"Inventory Points",t.pcs[p.id].ip)}${numberField(`pcs.${p.id}.ap`,"AP",t.pcs[p.id].ap,1)}${numberField(`pcs.${p.id}.def`,"DEF",t.pcs[p.id].def)}${numberField(`pcs.${p.id}.defenseBonus`,"Defense-roll bonus",t.pcs[p.id].defenseBonus)}</fieldset>`).join("")}</div><h3>${ENCOUNTERS[k].name} Enemies</h3><div class="tweak-grid">${Object.entries(t[k]).map(([type,s])=>`<fieldset><legend>${type[0].toUpperCase()+type.slice(1)}</legend>${npcControl(`${k}.${type}`,s.control)}${aiBehaviorSelect(`${k}.${type}`,s.aiBehavior||"optimal_killer","npc")}${numberField(`${k}.${type}.count`,"Count",s.count,0,locked)}${numberField(`${k}.${type}.hp`,"HP",s.hp,1)}${numberField(`${k}.${type}.ap`,"AP",s.ap,1)}${numberField(`${k}.${type}.atk`,"ATK",s.atk)}${numberField(`${k}.${type}.def`,"DEF",s.def)}${numberField(`${k}.${type}.dodge`,"Dodge",s.dodge)}${numberField(`${k}.${type}.threat`,"Threat",s.threat)}${k==="troll"?toggleField(`${k}.${type}.bossEdgesEnabled`,"Enable Boss Edges",s.bossEdgesEnabled!==false):""}${defendControls(`${k}.${type}`,s)}</fieldset>`).join("")}</div><div class="footer-actions"><button id="resetTweaks">Reset published values</button><button id="beginConfigured" class="primary">Begin ${ENCOUNTERS[k].name}</button></div></section>`;document.querySelectorAll("[data-tweak]").forEach(input=>input.onchange=()=>{setTweak(input.dataset.tweak,Math.max(Number(input.min)||0,Math.floor(Number(input.value)||0)));save()});document.querySelectorAll("[data-toggle]").forEach(input=>input.onchange=()=>{setTweak(input.dataset.toggle,input.checked);save()});document.querySelectorAll("[data-policy]").forEach(select=>select.onchange=()=>{setTweak(select.dataset.policy,select.value);commit()});document.querySelectorAll("[data-control]").forEach(select=>select.onchange=()=>{setTweak(select.dataset.control,select.value);commit()});document.querySelectorAll("[data-range]").forEach(input=>input.oninput=()=>{setTweak(input.dataset.range,Number(input.value));input.closest("label").querySelector("output").textContent=input.value+"%";save()});bindAISettings();$("#openPlacement").onclick=()=>openPlacementModal(k);if(locked)$("#resetPlacement").onclick=()=>resetPlacement(k);$("#resetTweaks").onclick=()=>{state.tweaks=defaultTweaks();commit()};$("#beginConfigured").onclick=()=>startEncounter(k)}
function makeConfiguredEnemies(key){let base=ENCOUNTERS[key].enemies(),groups=state.tweaks[key],placement=placementFor(key),out=[];for(const [type,s] of Object.entries(groups)){let template=base.find(e=>e.type===type);for(let i=1;i<=s.count;i++){let id=`${type}${i}`;out.push({...deep(template),id,name:type==="troll"?(s.count===1?"Troll":`Troll ${i}`):`${template.name.replace(/ \d+$/,'')} ${i}`,hp:s.hp,maxHp:s.hp,ap:s.ap,maxAp:s.ap,atk:s.atk,def:s.def,dodge:s.dodge,threat:s.threat,zone:placement?.enemies?.[id]??template.zone,control:s.control||"rigid",aiBehavior:s.aiBehavior||"optimal_killer",defendPolicy:s.defendPolicy,defendOdds:s.defendOdds,defendHpThreshold:s.defendHpThreshold,bossEdgesEnabled:type==="troll"&&s.bossEdgesEnabled!==false})}}return out}
function configuredUsesAI(key){return Object.values(state.tweaks.pcs).some(x=>x.control==="ai")||Object.values(state.tweaks[key]).some(x=>x.control==="ai")}
function startEncounter(key){if(configuredUsesAI(key)&&!aiKey()){showModal(`<p class="eyebrow">ChatGPT API setup</p><h2>API key required</h2><p>Save an OpenAI API key before starting an encounter with AI-controlled actors.</p><div class="footer-actions"><button id="closeKeyWarning" class="primary">Return to tweaks</button></div>`);$("#closeKeyWarning").onclick=closeModal;return}let c=ENCOUNTERS[key],placement=placementFor(key);state.screen="battle";state.battle={key,name:c.name,zones:c.zones,links:c.links,round:1,phase:"pc",pcs:deep(PC_TEMPLATES).map(p=>{let s=state.tweaks.pcs[p.id];return{...p,side:"pc",hp:s.hp,maxHp:s.hp,stamina:s.stamina,maxStamina:s.stamina,mana:s.mana,maxMana:s.mana,ip:s.ip,ap:s.ap,maxAp:s.ap,def:s.def,defenseBonus:s.defenseBonus,control:s.control,aiBehavior:s.aiBehavior||"role_faithful",zone:placement?.pcs?.[p.id]??c.start,conditions:[],acted:false,prepared:null,alive:true,attacksThisPhase:0,attacksPreviousPhase:0,reactionDoctrineActive:false}}),enemies:makeConfiguredEnemies(key),selected:null,log:[],metrics:{noRoll:0,npcDefRolls:0,pcDefRolls:0,multi:0,multiMitigate:0,multiZero:0,preparedDeclared:0,preparedTriggered:0,protect:0,finishing:0,allOffense:0,repeated:0,rules:0,apExpired:0,moves:0,rangeQuestions:0,regenAllowed:0,regenSuppressed:0,edgeRecover:0,ai:{requests:0,decisions:0,retries:0,failures:0,latencyMs:0,inputTokens:0,outputTokens:0,totalTokens:0}},aiDecisions:[],abilityUses:{},rounds:[],started:Date.now()};if(key==="troll")state.battle.enemies.forEach(e=>e.edges=e.bossEdgesEnabled?3:0);log(`Encounter begins: ${c.name}. PCs act first.`);if(key==="troll")log(`Boss Edges are ${state.battle.enemies.some(e=>e.bossEdgesEnabled)?"enabled":"disabled"}.`,"system");if(key==="troll")log("Prior investigation established that Persistent Damage reliably stops a troll's regeneration.","system");if(!state.battle.enemies.length){finishEncounter("victory");return}continuePCPhase()}

function battleView(){let b=state.battle;app.innerHTML=`<div class="game"><section><div class="panel battle-head"><div><p class="eyebrow">${b.name}</p><h2>Round ${b.round} · ${b.phase==="pc"?"PC phase":"Enemy phase"}</h2></div><div class="round">${b.phase==="pc"?"Choose any unacted PC":"Enemy turn resolving"}</div></div><div class="map">${mapHtml()}</div><div class="cards">${b.pcs.map(pcCard).join("")}</div><div class="panel turn-controls">${controlsHtml()}</div></section><aside class="sidebar"><section class="panel"><h3>Visible opposition</h3>${b.enemies.filter(e=>e.alive).map(e=>`<div class="resource"><span>${e.name} · ${b.zones[e.zone]}</span><b>${enemyHealth(e)}</b></div>`).join("")||"None"}</section><section class="panel"><h3>Combat log</h3><div class="log">${b.log.map(x=>`<p class="${x.kind}">${x.text}</p>`).join("")}</div></section><details class="panel doctrine"><summary>Rigid GM Doctrine</summary>${doctrine()}</details></aside></div>`;let le=$(".log");if(le)le.scrollTop=le.scrollHeight;bindBattle()}
function enemyHealth(e){let q=e.hp/e.maxHp;return q>.75?"Unhurt":q>.5?"Wounded":q>.25?"Badly wounded":"Near defeat"}
function mapHtml(){let b=state.battle;return b.zones.map((z,i)=>`${i?'<div class="connector">→</div>':''}<div class="zone ${b.selected&&b.pcs.find(p=>p.id===b.selected)?.zone===i?'active':''}"><b>${z}</b>${b.pcs.filter(p=>p.zone===i&&p.hp>0).map(p=>`<span class="token pc">${p.name}</span>`).join("")}${b.enemies.filter(e=>e.zone===i&&e.alive).map(e=>`<span class="token enemy">${e.name}</span>`).join("")}</div>`).join("")}
function pcCard(p){return`<button class="card ${state.battle.selected===p.id?'selected':''} ${p.hp<=0?'down':''}" data-pc="${p.id}" ${p.acted||p.hp<=0||(isAutomated(p)&&!isAIControlled(p))?'disabled':''}><h3>${p.name}</h3><div class="statline"><span>${p.role}</span><b>${p.ap} AP</b></div><div class="bar hp"><i style="width:${100*p.hp/p.maxHp}%"></i></div><div class="statline"><span>HP ${p.hp}/${p.maxHp}</span><span>DEF ${p.def}</span></div><div class="statline"><span>Stamina ${p.stamina}/${p.maxStamina}</span>${p.maxMana?`<span>Mana ${p.mana}/${p.maxMana}</span>`:""}<span>IP ${p.ip}</span></div><small>${state.battle.zones[p.zone]} · ${doctrineName(p)}${p.conditions.length?" · "+p.conditions.join(", "):""}</small></button>`}
function controlsHtml(){let b=state.battle,p=b.pcs.find(x=>x.id===b.selected);if(b.phase!=="pc")return"<p>The enemy phase is resolving.</p>";if(!p)return`<h3>Select the next PC</h3><p>Turn order is yours each round. Completed and unconscious characters cannot be selected.</p>`;if(isAIControlled(p))return`<h3>${p.name}'s turn</h3><p>${aiBehaviorName(p)} will control this character only after you start the turn.</p><div class="footer-actions"><button id="startAITurn" class="primary">Start AI turn</button></div>`;let basics=[{id:"move",name:"Move",ap:1},{id:"consumable",name:"Use Consumable",ap:1},{id:"recover",name:"Recover",ap:1},{id:"prepare",name:"Prepare Action",ap:0}];return`<h3>${p.name}'s turn</h3><div class="actions">${[...p.abilities,...basics].map(a=>`<button class="action" data-action="${a.id}" ${legalBasic(p,a)?'':'disabled'}>${a.name}<small>${costText(a)}${a.type?` · ${a.type}`:""}</small></button>`).join("")}</div><div class="footer-actions"><button id="endTurn" class="primary">End ${p.name}'s turn</button></div>`}
function costText(a){let x=[];if(a.ap)x.push(a.ap+" AP");if(a.stamina)x.push(a.stamina+" stamina");if(a.mana)x.push(a.mana+" mana");return x.join(", ")||"No immediate cost"}
function legalBasic(p,a){if(p.conditions.includes("Incapacitated")&&a.id!=="recover")return false;if(a.id==="prepare")return p.ap>0;if(a.id==="move")return p.ap>=1;if(a.id==="consumable")return p.ap>=1&&p.ip>0&&(p.hp<p.maxHp||p.stamina<p.maxStamina||p.mana<p.maxMana);if(a.id==="recover")return p.ap>=1&&state.battle.pcs.some(x=>distance(p.zone,x.zone)===0&&x.conditions.length);return p.ap>=a.ap&&p.stamina>=a.stamina&&p.mana>=a.mana}
function bindBattle(){document.querySelectorAll("[data-pc]").forEach(x=>x.onclick=()=>{state.battle.selected=x.dataset.pc;commit()});document.querySelectorAll("[data-action]").forEach(x=>x.onclick=()=>chooseAction(x.dataset.action));let ai=$("#startAITurn");if(ai)ai.onclick=()=>runAITurn(currentPC());let e=$("#endTurn");if(e)e.onclick=endPCTurn}

function chooseAction(id){let p=currentPC();if(id==="move")return chooseMove(p);if(id==="consumable")return chooseConsumable(p);if(id==="recover")return chooseRecover(p);if(id==="prepare")return choosePrepare(p);let a=p.abilities.find(x=>x.id===id);if(a.type==="heal"||a.type==="multiheal")chooseHeal(p,a);else if(a.type==="rush")chooseRush(p,a);else chooseAttack(p,a)}
function currentPC(){return state.battle.pcs.find(x=>x.id===state.battle.selected)}
function showModal(html,className=""){modalRoot.innerHTML=`<div class="modal-back"><section class="modal ${className}">${html}</section></div>`}
function closeModal(){modalRoot.innerHTML=""}
function choiceModal(title,desc,items,onPick){showModal(`<h2>${title}</h2>${desc?`<p>${desc}</p>`:""}<div class="choices">${items.map((x,i)=>`<button class="choice" data-choice="${i}">${x.label}${x.note?`<small>${x.note}</small>`:""}</button>`).join("")}</div><div class="footer-actions"><button id="cancelModal">Cancel</button></div>`);document.querySelectorAll("[data-choice]").forEach(b=>b.onclick=()=>{let x=items[+b.dataset.choice];closeModal();onPick(x)});$("#cancelModal").onclick=closeModal}
function chooseMove(p){let opts=adjacent(p.zone).filter(x=>x.cost<=p.ap).map(x=>({label:state.battle.zones[x.zone],note:x.cost===1?"1 Move":"Requires 2 Moves",zone:x.zone,cost:x.cost}));choiceModal("Move where?","Difficult connections consume the listed number of Moves.",opts,x=>{p.ap-=x.cost;p.zone=x.zone;state.battle.metrics.moves+=x.cost;log(`${p.name} moves to ${state.battle.zones[x.zone]} (${x.cost} AP).`);recordUse(p,"Move");commit()})}
function chooseConsumable(p){let items=[];if(p.hp<p.maxHp)items.push({label:"Restore 50 HP",kind:"hp"});if(p.stamina<p.maxStamina)items.push({label:"Restore 5 stamina",kind:"stamina"});if(p.mana<p.maxMana)items.push({label:"Restore 6 mana",kind:"mana"});choiceModal("Use Consumable","Costs 1 AP and 1 Inventory Point.",items,x=>{p.ap--;p.ip--;if(x.kind==="hp")p.hp=Math.min(p.maxHp,p.hp+50);if(x.kind==="stamina")p.stamina=Math.min(p.maxStamina,p.stamina+5);if(x.kind==="mana")p.mana=Math.min(p.maxMana,p.mana+6);log(`${p.name} uses supplies to restore ${x.kind}.`);recordUse(p,"Use Consumable");commit()})}
function chooseRecover(p){let items=state.battle.pcs.filter(x=>x.zone===p.zone&&x.conditions.length).flatMap(x=>x.conditions.map(c=>({label:`Remove ${c} from ${x.name}`,target:x,condition:c})));choiceModal("Recover","Remove one condition at Range 0.",items,x=>{p.ap--;x.target.conditions=x.target.conditions.filter(c=>c!==x.condition);log(`${p.name} removes ${x.condition} from ${x.target.name}.`);recordUse(p,"Recover");commit()})}
function choosePrepare(p){let abilities=p.abilities.filter(a=>a.type==="attack"||a.type==="bleed"||a.type==="push").filter(a=>legalBasic(p,a));let items=[];for(const a of abilities)for(const trigger of ["Enemy enters this ability's range","Enemy attacks an ally in my zone"] )items.push({label:a.name,note:trigger,a,trigger});choiceModal("Prepare an action","The first matching observable trigger before round end will offer the prepared action.",items,x=>{p.prepared={ability:x.a.id,trigger:x.trigger};state.battle.metrics.preparedDeclared++;log(`${p.name} prepares ${x.a.name}: “${x.trigger}.”`);commit()})}
function chooseHeal(p,a){let candidates=state.battle.pcs.filter(x=>x.hp<x.maxHp&&distance(p.zone,x.zone)<=a.maxRange);if(a.type==="heal")choiceModal(a.name,"Choose one target.",candidates.map(x=>({label:x.name,note:`${x.hp}/${x.maxHp} HP`,target:x})),x=>resolveHeal(p,a,[x.target]));else chooseMultiple(a.name,candidates,2,3,targets=>resolveHeal(p,a,targets))}
function resolveHeal(p,a,targets){pay(p,a);for(const t of targets)t.hp=Math.min(t.maxHp,t.hp+a.power+(p.id==="elian"?5:0));log(`${p.name} uses ${a.name} on ${targets.map(x=>x.name).join(", ")}.`);recordUse(p,a.name);commit()}
function chooseRush(p,a){let zones=adjacent(p.zone).filter(x=>x.cost===1&&state.battle.enemies.some(e=>e.alive&&e.zone===x.zone));choiceModal(a.name,"Move, then attack an enemy in the destination.",zones.map(x=>({label:state.battle.zones[x.zone],zone:x.zone})),x=>{p.zone=x.zone;state.battle.metrics.moves++;chooseAttack(p,a)})}
function chooseAttack(p,a){let candidates=state.battle.enemies.filter(e=>e.alive&&distance(p.zone,e.zone)>=a.minRange&&distance(p.zone,e.zone)<=a.maxRange);if(a.type==="multi")return chooseMultiple(a.name,candidates,a.minTargets,a.maxTargets,ts=>resolvePCAttack(p,a,ts));choiceModal(a.name,`Choose a target. ${candidates[0]?"The GM reveals only qualitative difficulty.":""}`,candidates.map(e=>({label:e.name,note:`${enemyHealth(e)} · ${qualitative(e.dodge+a.attackBonus)}`,target:e})),x=>{if(a.type==="push")choosePushDestination(p,a,x.target);else resolvePCAttack(p,a,[x.target])})}
function choosePushDestination(p,a,target){let zs=adjacent(target.zone).filter(x=>x.cost===1);choiceModal("Choose forced movement",`If ${a.name} deals damage, push ${target.name} into:`,[{label:"Do not push",zone:null},...zs.map(x=>({label:state.battle.zones[x.zone],zone:x.zone}))],x=>resolvePCAttack(p,a,[target],x.zone))}
function chooseMultiple(title,candidates,min,max,done){let picked=[];function draw(){showModal(`<h2>${title}</h2><p>Choose ${min}–${max} targets.</p><div class="choices">${candidates.map(x=>`<button class="choice" data-id="${x.id}">${picked.includes(x.id)?"✓ ":""}${x.name}</button>`).join("")}</div><div class="footer-actions"><button id="cancelModal">Cancel</button><button id="confirmMulti" class="primary" ${picked.length<min?'disabled':''}>Confirm ${picked.length}</button></div>`);document.querySelectorAll("[data-id]").forEach(b=>b.onclick=()=>{let id=b.dataset.id;picked=picked.includes(id)?picked.filter(x=>x!==id):picked.length<max?[...picked,id]:picked;draw()});$("#cancelModal").onclick=closeModal;$("#confirmMulti").onclick=()=>{closeModal();done(candidates.filter(x=>picked.includes(x.id)))}}draw()}
function pay(p,a){p.ap-=a.ap;p.stamina-=a.stamina;p.mana-=a.mana}
function enemyShouldDefend(e,a){if(e.ap<=0)return false;if(e.defendPolicy==="always")return true;if(e.defendPolicy==="random")return roll()<=e.defendOdds;if(e.defendPolicy==="hp")return e.hp/e.maxHp*100<=e.defendHpThreshold;return a.type==="multi"||a.power>=55||a.type==="bleed"||a.type==="push"}
function countMetric(name){let m=state.battle.metrics;m[name]=(m[name]||0)+1}
function resolvePCAttack(p,a,targets,pushZone=null,prepared=false,done=()=>{}){if(!prepared)pay(p,a);recordUse(p,a.name);if(a.type==="multi")state.battle.metrics.multi++;let index=0;function finish(){if(prepared)state.battle.metrics.preparedTriggered++;checkVictory();commit();done()}function next(){if(index>=targets.length){finish();return}let e=targets[index++];applyToTarget(isAIControlled(e)?aiNPCShouldDefend(e,a):enemyShouldDefend(e,a));next()}function applyToTarget(shouldDefend){let e=targets[index-1],damage=a.power,defended=false,r=null;if(a.type==="multi"){if(shouldDefend&&e.ap>0){e.ap--;defended=true;damage=Math.max(0,damage-e.def);state.battle.metrics.multiMitigate++;if(damage===0)state.battle.metrics.multiZero++;log(`${e.name} Defends against the multi-target attack and applies DEF: ${damage} damage.`,"roll")}}else if(shouldDefend&&e.ap>0){e.ap--;defended=true;r=roll();countMetric("npcDefRolls");damage=r>=96?0:r<=e.dodge+a.attackBonus?a.power:Math.max(0,a.power-e.def);log(`${e.name} Defends. Roll ${String(r).padStart(2,"0")} vs TN ${e.dodge+a.attackBonus}: ${damage} damage.`,"roll")}else state.battle.metrics.noRoll++;e.hp=Math.max(0,e.hp-damage);log(`${p.name}'s ${a.name} deals ${damage} damage to ${e.name}${defended?" after defense":""}.`,"damage");if(damage>0&&a.type==="bleed"&&!e.conditions.includes("Persistent Damage"))e.conditions.push("Persistent Damage");if(damage>0&&a.type==="push"&&pushZone!==null)e.zone=pushZone;if(e.hp===0){e.alive=false;log(`${e.name} is defeated.`)}}next()}
function recordUse(p,name){let k=p.id+":"+name;state.battle.abilityUses[k]=(state.battle.abilityUses[k]||0)+1;if(state.battle.abilityUses[k]>1)state.battle.metrics.repeated++}

function isAutomated(p){return p&&p.control&&p.control!=="manual"}
function doctrineName(p){return p.control==="allout"?"All-Out Attacker":p.control==="prepared"?"Always Prepared":p.control==="survivor"?"Reactive Survivor":p.control==="ai"?aiBehaviorName(p):"Manual"}
function continuePCPhase(){if(state.autoPause){render();return}if(state.screen!=="battle"||state.battle.phase!=="pc")return;let p=state.battle.pcs.find(x=>x.hp>0&&!x.acted&&isAutomated(x)&&!isAIControlled(x));if(!p){state.battle.selected=null;commit();return}state.battle.selected=p.id;runAutomatedTurn(p)}
function doctrineReserve(p){if(p.control==="prepared")return 1;if(p.control==="survivor"&&(p.hp/p.maxHp<=.5||p.attacksPreviousPhase>=2))return 1;return 0}
function affordableFor(p,a,reserve=0){return p.ap>=a.ap+reserve&&p.stamina>=a.stamina&&p.mana>=a.mana}
function autoMoveToward(p,target,reserve=0){let budget=p.ap-reserve,options=adjacent(p.zone).filter(x=>x.cost<=budget&&distance(x.zone,target.zone)<distance(p.zone,target.zone)).sort((a,b)=>distance(a.zone,target.zone)-distance(b.zone,target.zone)||a.cost-b.cost||a.zone-b.zone);if(!options.length)return false;let step=options[0];p.ap-=step.cost;p.zone=step.zone;state.battle.metrics.moves+=step.cost;recordUse(p,"Move");log(`${p.name} moves to ${state.battle.zones[p.zone]} under ${doctrineName(p)}.`);return true}
function autoHealPriority(p,threshold){if(p.id!=="elian")return false;let mend=p.abilities.find(a=>a.id==="mend");if(!affordableFor(p,mend,0))return false;let fallen=state.battle.pcs.filter(x=>x.hp===0).sort((a,b)=>a.hp-b.hp)[0];if(fallen){if(distance(p.zone,fallen.zone)<=mend.maxRange){resolveHeal(p,mend,[fallen]);log(`${p.name}'s doctrine revives ${fallen.name}.`);return true}return autoMoveToward(p,fallen,0)}if(threshold===null)return false;let wounded=state.battle.pcs.filter(x=>x.hp>0&&x.hp/x.maxHp<threshold).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp||a.hp-b.hp)[0];if(!wounded)return false;if(distance(p.zone,wounded.zone)<=mend.maxRange){resolveHeal(p,mend,[wounded]);return true}return autoMoveToward(p,wounded,doctrineReserve(p))}
function autoAttackOptions(p,reserve){let enemies=state.battle.enemies.filter(e=>e.alive),out=[];for(const a of p.abilities.filter(x=>["attack","bleed","push","multi","rush"].includes(x.type))){if(!affordableFor(p,a,reserve))continue;if(a.type==="multi"){let valid=enemies.filter(e=>distance(p.zone,e.zone)>=a.minRange&&distance(p.zone,e.zone)<=a.maxRange).sort((x,y)=>x.hp-y.hp||x.id.localeCompare(y.id));if(valid.length>=a.minTargets){let targets=valid.slice(0,a.maxTargets);out.push({a,targets,primary:targets[0],score:a.power*targets.length})}continue}if(a.type==="rush"){for(const step of adjacent(p.zone).filter(x=>x.cost===1))for(const e of enemies.filter(x=>x.zone===step.zone))out.push({a,targets:[e],primary:e,score:a.power,rushZone:step.zone});continue}for(const e of enemies.filter(e=>distance(p.zone,e.zone)>=a.minRange&&distance(p.zone,e.zone)<=a.maxRange))out.push({a,targets:[e],primary:e,score:a.power})}return out.sort((x,y)=>x.primary.hp-y.primary.hp||y.score-x.score||x.a.ap-y.a.ap||x.a.id.localeCompare(y.a.id))}
function autoOffense(p,reserve){let options=autoAttackOptions(p,reserve);if(options.length){let x=options[0];if(x.rushZone!==undefined)p.zone=x.rushZone;if(x.targets.some(isAIControlled)){resolvePCAttack(p,x.a,x.targets,null,false,()=>runAutomatedTurn(p));return"pending"}resolvePCAttack(p,x.a,x.targets);return true}let target=state.battle.enemies.filter(e=>e.alive).sort((a,b)=>a.hp-b.hp||a.id.localeCompare(b.id))[0];return target?autoMoveToward(p,target,reserve):false}
function runAutomatedTurn(p){if(!p.autoRunning){p.autoRunning=true;p.autoLogStart=state.battle.log.length;log(`${p.name} begins an automated ${doctrineName(p)} turn.`);p.reactionDoctrineActive=p.control==="prepared"||(p.control==="survivor"&&(p.hp/p.maxHp<=.5||p.attacksPreviousPhase>=2))}let threshold=p.control==="prepared"?.5:p.control==="survivor"?.35:null,safety=0;while(state.screen==="battle"&&p.hp>0&&!p.acted&&safety++<30){if(p.conditions.includes("Incapacitated")){p.ap=Math.min(p.ap,1);p.conditions=p.conditions.filter(x=>x!=="Incapacitated");p.ap--;recordUse(p,"Recover");log(`${p.name} spends their only AP Recovering from Incapacitated.`);break}if(autoHealPriority(p,threshold))continue;let reserve=doctrineReserve(p),result=autoOffense(p,reserve);if(result==="pending")return;if(!result)break}if(safety>=30)log(`${p.name}'s automated turn stopped at the safety limit.`);let logStart=p.autoLogStart;delete p.autoLogStart;delete p.autoRunning;if(state.screen==="battle")finalizePCTurn(p);state.autoPause={title:`${p.name} — ${doctrineName(p)}`,lines:state.battle.log.slice(logStart).map(x=>x.text)};commit()}

function finalizePCTurn(p){if(p.ap===0)state.battle.metrics.allOffense++;p.acted=true;state.battle.selected=null;log(`${p.name} ends their turn with ${p.ap} AP retained.`)}
function advanceAfterPCTurn(){let next=()=>state.battle.pcs.filter(x=>x.hp>0).every(x=>x.acted)?enemyPhase():continuePCPhase();if(state.battle.key==="troll")trollEdges(next);else next()}
function endPCTurn(){let p=currentPC();if(!p)return;finalizePCTurn(p);advanceAfterPCTurn()}
function trollEdges(done,index=0){let trolls=state.battle.enemies.filter(e=>e.alive&&e.type==="troll");if(index>=trolls.length){done();return}trollEdgeOne(trolls[index],()=>trollEdges(done,index+1))}
function trollEdgeOne(t,done){if(t.edges<=0){done();return}if(isAIControlled(t)){runAITrollEdge(t,done);return}trollEdgeOneRigid(t,done)}
function trollEdgeOneRigid(t,done){t.edges--;if(t.conditions.includes("Persistent Damage")){t.conditions=[];state.battle.metrics.edgeRecover++;log(`${t.name} spends an Edge to Recover Persistent Damage.`);done();return}let targets=conscious().sort(targetOrder);let near=targets.find(p=>distance(t.zone,p.zone)===0);if(near){enemySingle(t,near,"Crushing Strike",t.atk+(t.enraged?10:0),true,null,done);return}let ranged=targets.find(p=>distance(t.zone,p.zone)<=1);if(ranged){enemySingle(t,ranged,"Hurl Debris",50+(t.enraged?10:0),true,null,done);return}if(targets[0])moveEnemyToward(t,targets[0],true);done()}
function conscious(){return state.battle.pcs.filter(p=>p.hp>0)}
function targetOrder(a,b){return a.hp/a.maxHp-b.hp/b.maxHp||a.hp-b.hp||["ardan","sera","mira","elian"].indexOf(a.id)-["ardan","sera","mira","elian"].indexOf(b.id)}
function enemyPhase(){let b=state.battle;b.phase="enemy";b.enemyIndex=0;log("Enemy phase begins.");for(const p of b.pcs)p.attacksThisPhase=0;prepareAIEnemyPhase(processEnemy)}
function processEnemy(){let b=state.battle;if(conscious().length===0){finishEncounter("defeat");return}let living=b.enemies.filter(x=>x.alive);if(b.enemyIndex>=living.length){delete b.aiEnemyPlans;endRound();return}let e=living[b.enemyIndex],done=()=>{b.enemyIndex++;processEnemy()};if(isAIControlled(e)){runAINPCPlan(e,done);return}if(b.key==="troll"){runTrollNormal(e,done);return}runBanditStep(e,done)}
function runBanditStep(e,done){if(e.ap<=0||!conscious().length){done();return}let t=conscious().slice().sort((a,b)=>distance(e.zone,a.zone)-distance(e.zone,b.zone)||targetOrder(a,b))[0];if(e.type==="leader"&&e.ap>=3){let allies=state.battle.enemies.filter(x=>x.alive&&x.id!==e.id&&distance(e.zone,x.zone)===0&&!x.rallied).slice(0,4);if(allies.length>=2){e.ap-=3;allies.forEach(x=>x.rallied=true);log(`${e.name} uses Rallying Order on ${allies.map(x=>x.name).join(", ")}.`);done();return}}let again=()=>runBanditStep(e,done),d=distance(e.zone,t.zone);if(e.type==="archer"&&d<=rangeForArcher(e)){if(e.ap>=2)enemySingle(e,t,"Aimed Shot",50+(e.rallied?10:0),false,null,again,2);else done();return}if(d===0){if(e.type==="bruiser"&&e.ap>=2)enemySingle(e,t,"Concussive Blow",50+(e.rallied?10:0),false,"Incapacitated",again,2);else if(e.type==="melee"&&!e.reckless){e.reckless=true;enemySingle(e,t,"Reckless Assault",45+(e.rallied?10:0),false,null,again)}else enemySingle(e,t,"Strike",e.atk+(e.rallied?10:0),false,null,again);return}moveEnemyToward(e,t);if(e.ap===1&&e.type!=="melee"&&e.type!=="archer")done();else again()}
function rangeForArcher(e){return e.zone===4?2:1}
function moveEnemyToward(e,t,edge=false){let budget=edge?1:e.ap,options=adjacent(e.zone).filter(x=>x.cost<=budget).sort((a,b)=>distance(a.zone,t.zone)-distance(b.zone,t.zone)||a.cost-b.cost||a.zone-b.zone);if(!options.length){if(!edge)e.ap=0;log(`${e.name} cannot complete an available connection and ends its movement.`);return false}let step=options[0];e.zone=step.zone;if(!edge)e.ap-=step.cost;log(`${e.name} moves to ${state.battle.zones[e.zone]} (${step.cost} AP).`);checkPrepared(e);return true}
function checkPrepared(e,done=()=>{}){let prepared=state.battle.pcs.filter(x=>x.hp>0&&x.prepared&&x.prepared.trigger.startsWith("Enemy enters")),index=0;function next(){if(!e.alive||index>=prepared.length){done();return}let p=prepared[index++],a=p.abilities.find(x=>x.id===p.prepared.ability);if(p.ap>=a.ap&&p.stamina>=a.stamina&&p.mana>=a.mana&&distance(p.zone,e.zone)<=a.maxRange){p.prepared=null;pay(p,a);log(`${p.name}'s prepared ${a.name} triggers.`);resolvePCAttack(p,a,[e],null,true,next);return}next()}next()}
function runTrollNormal(t,done){if(!t.alive){done();return}if(!t.normalStarted){t.normalStarted=true;if(t.conditions.includes("Incapacitated")){t.conditions=t.conditions.filter(x=>x!=="Incapacitated");t.ap=0;log("The troll spends its turn Recovering from Incapacitated.");t.normalStarted=false;done();return}if(t.conditions.includes("Persistent Damage")){state.battle.metrics.regenSuppressed++;log("The troll's Regeneration is suppressed.")}else{t.hp=Math.min(t.maxHp,t.hp+50);state.battle.metrics.regenAllowed++;log("The troll regenerates 50 HP.")}if(t.hp<=600&&!t.enraged){t.enraged=true;t.def-=10;log("The troll becomes Enraged.")}}if(t.ap<=0||!conscious().length){t.normalStarted=false;done();return}let near=conscious().filter(p=>p.zone===t.zone).sort(targetOrder);if(near.length>=2&&t.ap>=2){t.ap-=2;enemyMulti(t,near.slice(0,3),"Sweeping Blow",50+(t.enraged?10:0),()=>runTrollNormal(t,done));return}let targets=conscious().sort((a,b)=>distance(t.zone,a.zone)-distance(t.zone,b.zone)||targetOrder(a,b)),x=targets[0];if(!t.enraged&&t.hp<900&&t.ap===1){t.normalStarted=false;done();return}if(distance(t.zone,x.zone)===0)enemySingle(t,x,"Crushing Strike",60+(t.enraged?10:0),false,null,()=>runTrollNormal(t,done));else if(distance(t.zone,x.zone)<=1)enemySingle(t,x,"Hurl Debris",50+(t.enraged?10:0),false,null,()=>runTrollNormal(t,done));else{moveEnemyToward(t,x);runTrollNormal(t,done)}}
function enemySingle(e,target,name,atk,edge=false,condition=null,done=()=>commit(),apCost=1){if(!edge&&e.ap<apCost){log(`${e.name} cannot afford ${name} and ends its turn.`);e.ap=0;done();return}if(!edge)e.ap-=apCost;let prepared=state.battle.pcs.filter(x=>x.hp>0&&x.id!==target.id&&x.zone===target.zone&&x.prepared&&x.prepared.trigger.startsWith("Enemy attacks")),index=0;function continueAttack(){if(!e.alive){log(`${e.name}'s declared attack is interrupted by defeat.`);done();return}if(index>=prepared.length){reactionPrompt(e,target,name,atk,false,condition,done);return}let p=prepared[index++],a=p.abilities.find(x=>x.id===p.prepared.ability);if(p.ap>=a.ap&&p.stamina>=a.stamina&&p.mana>=a.mana&&distance(p.zone,e.zone)<=a.maxRange){p.prepared=null;pay(p,a);log(`${p.name}'s prepared ${a.name} triggers against ${e.name}.`);resolvePCAttack(p,a,[e],null,true,continueAttack);return}continueAttack()}continueAttack()}
function enemyMulti(e,targets,name,atk,done=()=>commit()){state.battle.metrics.multi++;let index=0;function next(){if(index>=targets.length){done();return}multiReactionPrompt(e,targets[index++],name,atk,next)}next()}
function legalReactions(target,source,multi){let out=[{id:"none",label:"Take the attack"}],canReact=!target.conditions.includes("Incapacitated");if(canReact&&target.ap>0)out.push({id:"defend",label:multi?"Defend — apply DEF":"Defend — roll percentile",note:"1 AP"});if(canReact&&!multi&&target.id==="mira"&&target.ap>0&&target.mana>=2)out.push({id:"gale",label:"Galeshield",note:"1 AP, 2 mana"});if(!multi){for(const p of state.battle.pcs.filter(x=>x.hp>0&&x.id!==target.id&&x.zone===target.zone&&x.ap>0&&!x.conditions.includes("Incapacitated"))){out.push({id:"protect",label:`${p.name} Protects without Defending`,protector:p,note:"1 AP"});if(p.ap>=2)out.push({id:"protectDefend",label:`${p.name} Protects, then Defends`,protector:p,note:"2 AP"})}let s=state.battle.pcs.find(x=>x.id==="sera");if(s&&s.hp>0&&s.zone===target.zone&&s.id!==target.id&&s.ap>0&&s.stamina>=2&&!s.conditions.includes("Incapacitated"))out.push({id:"intercede",label:"Sera uses Shielded Intercession",protector:s,note:"1 AP, 2 stamina; includes Defend"})}return out}
function automatedSeraReaction(target,opts){let s=state.battle.pcs.find(x=>x.id==="sera"&&isAutomated(x)&&x.hp>0&&x.id!==target.id);if(!s)return null;let threshold=s.control==="prepared"?.5:s.control==="survivor"?.35:null;if(threshold===null||target.hp/target.maxHp>threshold)return null;if(s.control==="prepared"&&!["mira","elian"].includes(target.id)){let endangeredMage=state.battle.pcs.some(x=>["mira","elian"].includes(x.id)&&x.hp>0&&x.hp/x.maxHp<=threshold);if(endangeredMage)return null}return opts.find(x=>x.id==="intercede"&&x.protector===s)||opts.find(x=>x.id==="protect"&&x.protector===s)||null}
function automatedReaction(target,opts){let sera=automatedSeraReaction(target,opts);if(sera)return sera;if(!isAutomated(target)||isAIControlled(target))return null;if(target.control==="allout")return opts.find(x=>x.id==="none");let active=target.control==="prepared"||(target.control==="survivor"&&target.reactionDoctrineActive);if(!active)return opts.find(x=>x.id==="none");return opts.find(x=>x.id==="gale")||opts.find(x=>x.id==="defend")||opts.find(x=>x.id==="none")}
function reactionPrompt(e,target,name,atk,multi=false,condition=null,done=()=>commit()){target.attacksThisPhase=(target.attacksThisPhase||0)+1;let opts=legalReactions(target,e,multi),automatic=aiPresetReaction(target,opts,atk,multi)||automatedReaction(target,opts);if(automatic){let actor=automatic.protector||target;log(`${actor.name}'s ${doctrineName(actor)} doctrine chooses ${automatic.label}.`);resolveEnemyHit(e,target,name,atk,automatic,multi,condition,done);return}let manual=opts.filter(o=>!o.protector||!isAIControlled(o.protector));choiceModal(`${e.name}: ${name}`,`${target.name} faces ${atk} ATK. ${qualitative(defenseTarget(target,e))}.`,manual,x=>resolveEnemyHit(e,target,name,atk,x,multi,condition,done))}
function applyCondition(target,condition){if(target.conditions.includes(condition))return;target.conditions.push(condition);if(condition==="Incapacitated")target.ap=Math.min(target.ap,1);log(`${target.name} becomes ${condition}.`)}
function resolveEnemyHit(e,target,name,atk,choice,multi,condition,done){let actual=target,damage=atk,mitigated=false;if(["protect","protectDefend","intercede"].includes(choice.id)){actual=choice.protector;actual.ap--;state.battle.metrics.protect++;if(choice.id==="intercede")actual.stamina-=2;log(`${actual.name} intercepts the attack aimed at ${target.name}.`)}if(multi&&choice.id==="defend"){actual.ap--;damage=Math.max(0,atk-actual.def);mitigated=true;state.battle.metrics.multiMitigate++;if(damage===0)state.battle.metrics.multiZero++;log(`${actual.name} spends 1 AP to apply DEF: ${damage} damage.`,"roll")}else if(!multi&&["defend","intercede","protectDefend"].includes(choice.id)){if(choice.id==="defend"||choice.id==="protectDefend")actual.ap--;let r=roll(),tn=defenseTarget(actual,e);countMetric("pcDefRolls");damage=r<=5?0:r<=tn?Math.max(0,atk-actual.def):atk;mitigated=damage<atk;log(`${actual.name} Defends. Roll ${String(r).padStart(2,"0")} vs TN ${tn}: ${damage} damage.`,"roll")}else if(choice.id==="gale"){actual.ap--;actual.mana-=2;let r=roll(),tn=e.threat+45;countMetric("pcDefRolls");damage=r<=5?0:r<=tn?Math.max(0,atk-actual.def-15-(e.type==="archer"?10:0)):atk;mitigated=damage<atk;log(`Mira uses Galeshield. Roll ${String(r).padStart(2,"0")} vs TN ${tn}: ${damage} damage.`,"roll")}else if(choice.id==="none"||choice.id==="protect")state.battle.metrics.noRoll++;actual.hp=Math.max(0,actual.hp-damage);log(`${e.name}'s ${name} deals ${damage} damage to ${actual.name}.`,"damage");if(damage>0&&condition)applyCondition(actual,condition);if(actual.hp===0)log(`${actual.name} falls unconscious.`);if(actual.id==="sera"&&mitigated&&actual.hp>0&&actual.ap>0&&actual.stamina>=2&&distance(actual.zone,e.zone)===0&&!isAutomated(actual)){choiceModal("Riposte available",`Sera received the mitigated or avoided result against ${e.name}.`,[{label:"Use Riposte",use:true,note:"1 AP, 2 stamina"},{label:"Do not Riposte",use:false}],x=>{if(x.use){actual.ap--;actual.stamina-=2;let a=actual.abilities.find(y=>y.id==="strike");resolvePCAttack(actual,a,[e],null,true);recordUse(actual,"Riposte")}done()});return}done()}
function multiReactionPrompt(e,t,name,atk,done){reactionPrompt(e,t,name,atk,true,null,done)}
function checkVictory(){if(state.battle.enemies.every(e=>!e.alive))finishEncounter("victory")}
function endRound(){let b=state.battle;for(const p of b.pcs)b.metrics.apExpired+=p.ap;for(const e of b.enemies)b.metrics.apExpired+=e.ap;b.rounds.push({round:b.round,pcsDown:b.pcs.filter(p=>p.hp===0).length,enemies:b.enemies.filter(e=>e.alive).length});b.round++;b.phase="pc";for(const p of b.pcs){p.attacksPreviousPhase=p.attacksThisPhase||0;p.ap=p.hp>0?(p.conditions.includes("Incapacitated")?1:p.maxAp):0;p.acted=p.hp===0;p.prepared=null}for(const e of b.enemies.filter(x=>x.alive)){e.ap=e.maxAp;if(e.type==="troll")e.edges=e.bossEdgesEnabled?3:0}b.selected=null;log(`Round ${b.round} begins. AP refreshes.`);continuePCPhase()}
function finishEncounter(outcome){if(state.screen!=="battle")return;let b=state.battle;state.results.push({key:b.key,name:b.name,outcome,rounds:b.round,elapsed:Date.now()-b.started,metrics:deep(b.metrics),aiDecisions:deep(b.aiDecisions||[]),abilityUses:deep(b.abilityUses),pcs:b.pcs.map(p=>({name:p.name,hp:p.hp,stamina:p.stamina,mana:p.mana,ip:p.ip})),log:deep(b.log)});state.screen="report";save();render()}

function aiReportHtml(r){let a=r.metrics.ai||{},decisions=r.aiDecisions||[];if(!a.requests&&!decisions.length)return"";return`<h3>ChatGPT API evidence</h3><div class="metrics">${Object.entries({Decisions:a.decisions||0,"API requests":a.requests||0,Retries:a.retries||0,"Failed attempts":a.failures||0,"Total latency (ms)":a.latencyMs||0,"Input tokens":a.inputTokens||0,"Output tokens":a.outputTokens||0,"Total tokens":a.totalTokens||0}).map(([k,v])=>`<div class="metric"><span>${k}</span><b>${v}</b></div>`).join("")}</div><div class="footer-actions"><button id="viewAIDecisions">View AI decisions</button></div>`}
function reportView(){let r=state.results.at(-1),m=r.metrics,rollMetrics={"NPC defense rolls":m.npcDefRolls||0,"PC defense rolls":m.pcDefRolls||0,...(m.defRolls?{"Earlier combined defense rolls":m.defRolls}:{})};app.innerHTML=`<section class="panel setup"><p class="eyebrow">${r.name} · ${r.outcome}</p><h2>Encounter Metrics</h2><div class="metrics">${Object.entries({Rounds:r.rounds,"No-roll attacks":m.noRoll,...rollMetrics,"Multi-target uses":m.multi,"AP spent mitigating":m.multiMitigate,"Prepared declared":m.preparedDeclared,"Prepared triggered":m.preparedTriggered,"Protect reactions":m.protect,"All-offense turns":m.allOffense,"Repeated actions":m.repeated,"AP expired":m.apExpired,"Moves":m.moves,"Regeneration allowed":m.regenAllowed,"Regeneration suppressed":m.regenSuppressed,"Edge Recovers":m.edgeRecover}).map(([k,v])=>`<div class="metric"><span>${k}</span><b>${v}</b></div>`).join("")}</div>${aiReportHtml(r)}<h3>End-state resources</h3>${r.pcs.map(p=>`<p>${p.name}: ${p.hp} HP, ${p.stamina} stamina${p.mana?`, ${p.mana} mana`:""}, ${p.ip} IP</p>`).join("")}<div class="footer-actions"><button id="viewLog">View event log</button><button id="continueReport" class="primary">Answer survey</button></div></section>`;$("#continueReport").onclick=openSurvey;$("#viewLog").onclick=()=>showModal(`<h2>Event log</h2><div class="log">${r.log.map(x=>`<p class="${x.kind}">${x.text}</p>`).join("")}</div><div class="footer-actions"><button onclick="document.querySelector('#modalRoot').innerHTML=''">Close</button></div>`);let ai=$("#viewAIDecisions");if(ai)ai.onclick=()=>showModal(`<h2>ChatGPT API decisions</h2><div class="ai-decision-log">${(r.aiDecisions||[]).map(d=>`<article><b>Round ${d.round} · ${escapeAIHtml(d.actor)} · ${escapeAIHtml(d.behavior)}</b><p>${escapeAIHtml(d.choice)}</p><p>${escapeAIHtml(d.reasoning)}</p><small>${d.kind} · ${d.latencyMs} ms · ${d.usage.totalTokens} tokens · ${d.retries} retries</small></article>`).join("")}</div><div class="footer-actions"><button onclick="document.querySelector('#modalRoot').innerHTML=''">Close</button></div>`)}
function openSurvey(){state.screen="survey";commit()}
function surveyView(){app.innerHTML=`<section class="panel setup survey"><p class="eyebrow">Player Debrief</p><h2>What happened at the table?</h2><p>Objective measurements are already recorded. Use these questions for decisions, expectations, uncertainty, and reasons the app cannot infer.</p>${surveyQuestions.map((q,i)=>`<label for="q${i}">${i+1}. ${q}</label><textarea id="q${i}">${state.survey[i]||""}</textarea>`).join("")}<div class="footer-actions"><button id="finishSurvey" class="primary">Finish test</button></div></section>`;surveyQuestions.forEach((_,i)=>$("#q"+i).oninput=e=>{state.survey[i]=e.target.value;save()});$("#finishSurvey").onclick=()=>{state.screen="complete";commit()}}
function aiCompleteHtml(r){let a=r.metrics.ai||{};if(!a.requests)return"";return`<h4>ChatGPT API</h4><div class="metrics"><div class="metric"><span>AI decisions</span><b>${a.decisions||0}</b></div><div class="metric"><span>Retries</span><b>${a.retries||0}</b></div><div class="metric"><span>Total latency (ms)</span><b>${a.latencyMs||0}</b></div><div class="metric"><span>Total tokens</span><b>${a.totalTokens||0}</b></div></div><div class="ai-decision-log">${(r.aiDecisions||[]).map(d=>`<article><b>Round ${d.round} · ${escapeAIHtml(d.actor)} · ${escapeAIHtml(d.behavior)}</b><p>${escapeAIHtml(d.choice)} — ${escapeAIHtml(d.reasoning)}</p><small>${d.kind} · ${d.latencyMs} ms · ${d.usage.totalTokens} tokens · ${d.retries} retries</small></article>`).join("")}</div>`}
function completeView(){app.innerHTML=`<section class="panel setup"><p class="eyebrow">Test complete</p><h2>Playtest Record</h2><p>The record remains in this browser until you restart the test.</p>${state.results.map(r=>`<h3>${r.name} — ${r.outcome}</h3><div class="metrics"><div class="metric"><span>Rounds</span><b>${r.rounds}</b></div><div class="metric"><span>NPC defense rolls</span><b>${r.metrics.npcDefRolls||0}</b></div><div class="metric"><span>PC defense rolls</span><b>${r.metrics.pcDefRolls||0}</b></div>${r.metrics.defRolls?`<div class="metric"><span>Earlier combined defense rolls</span><b>${r.metrics.defRolls}</b></div>`:""}<div class="metric"><span>AP expired</span><b>${r.metrics.apExpired}</b></div><div class="metric"><span>Repeated actions</span><b>${r.metrics.repeated}</b></div><div class="metric"><span>Moves</span><b>${r.metrics.moves}</b></div><div class="metric"><span>Protect reactions</span><b>${r.metrics.protect}</b></div></div>${aiCompleteHtml(r)}`).join("")}<h3>Player Debrief</h3>${surveyQuestions.map((q,i)=>`<p><b>${i+1}. ${q}</b><br>${state.survey[i]||"—"}</p>`).join("")}<div class="footer-actions"><button id="printBtn">Print / Save as PDF</button><button id="newTest" class="primary">Start another test</button></div></section>`;$("#printBtn").onclick=()=>window.print();$("#newTest").onclick=()=>{state.screen="setup";state.mode=null;commit()}}
function automatedTurnModal(){let pause=state.autoPause;if(!pause)return;showModal(`<p class="eyebrow">Automated PC turn</p><h2>${pause.title}</h2><div class="turn-summary">${pause.lines.map(x=>`<p>${x}</p>`).join("")}</div><div class="footer-actions"><button id="autoNext" class="primary">Next</button></div>`);$("#autoNext").onclick=advanceAutoPause}
function advanceAutoPause(){state.autoPause=null;closeModal();save();if(state.screen==="battle")advanceAfterPCTurn();else render()}
function render(){if(state.screen==="setup")setupView();else if(state.screen==="tweaks")tweakView();else if(state.screen==="battle")battleView();else if(state.screen==="report")reportView();else if(state.screen==="survey")surveyView();else completeView();if(state.autoPause)automatedTurnModal()}
$("#restartBtn").onclick=()=>{if(confirm("Erase the current test and its locally saved record?")){localStorage.removeItem(SAVE_KEY);state={screen:"setup",mode:null,results:[],survey:{},battle:null,tweaks:null};render()}};
render();
